namespace RonSijm.FluidHumidifier.Factories.Invoicing;

public class ProcurementPortalPreferenceFactory(string resourceName = null, Action<Humidifier.Invoicing.ProcurementPortalPreference> factoryAction = null) : ResourceFactory<Humidifier.Invoicing.ProcurementPortalPreference>(resourceName)
{

    internal List<InnerProcurementPortalPreferenceContactFactory> ContactsFactories { get; set; } = [];

    internal InnerProcurementPortalPreferenceTestEnvPreferenceFactory TestEnvPreferenceFactory { get; set; }

    internal InnerProcurementPortalPreferenceEinvoiceDeliveryPreferenceFactory EinvoiceDeliveryPreferenceFactory { get; set; }

    internal InnerProcurementPortalPreferenceProcurementPortalPreferenceSelectorFactory SelectorFactory { get; set; }

    protected override Humidifier.Invoicing.ProcurementPortalPreference Create()
    {
        var procurementPortalPreferenceResult = CreateProcurementPortalPreference();
        factoryAction?.Invoke(procurementPortalPreferenceResult);

        return procurementPortalPreferenceResult;
    }

    private Humidifier.Invoicing.ProcurementPortalPreference CreateProcurementPortalPreference()
    {
        var procurementPortalPreferenceResult = new Humidifier.Invoicing.ProcurementPortalPreference
        {
            GivenName = InputResourceName,
        };

        return procurementPortalPreferenceResult;
    }
    public override void CreateChildren(Humidifier.Invoicing.ProcurementPortalPreference result)
    {
        base.CreateChildren(result);

        result.Contacts = ContactsFactories.Any() ? ContactsFactories.Select(x => x.Build()).ToList() : null;
        result.TestEnvPreference ??= TestEnvPreferenceFactory?.Build();
        result.EinvoiceDeliveryPreference ??= EinvoiceDeliveryPreferenceFactory?.Build();
        result.Selector ??= SelectorFactory?.Build();
    }

} // End Of Class

